 31	/// The value types `defaults write` can set and mise can verify. Other plist
 32	/// types (arrays, dicts, dates, data) are not supported — config entries with
 33	/// those TOML types warn and are skipped.
 34	#[derive(Debug, Clone, PartialEq)]
 35	pub(crate) enum DefaultsValue {
 36	    Bool(bool),
 37	    Int(i64),
 38	    Float(f64),
 39	    Str(String),
 40	}
 41	
 42	impl DefaultsValue {
 43	    pub(crate) fn from_toml(value: &toml::Value) -> Option<Self> {
 44	        match value {
 45	            toml::Value::Boolean(b) => Some(Self::Bool(*b)),
 46	            toml::Value::Integer(i) => Some(Self::Int(*i)),
 47	            toml::Value::Float(f) => Some(Self::Float(*f)),
 48	            toml::Value::String(s) => Some(Self::Str(s.clone())),
 49	            _ => None,
 50	        }
 51	    }
 52	
 53	    /// type+value arguments for `defaults write <domain> <key> ...`
 54	    pub(crate) fn write_args(&self) -> Vec<String> {
 55	        match self {
 56	            Self::Bool(b) => vec!["-bool".into(), b.to_string()],
 57	            Self::Int(i) => vec!["-int".into(), i.to_string()],
 58	            Self::Float(f) => vec!["-float".into(), f.to_string()],
 59	            Self::Str(s) => vec!["-string".into(), s.clone()],
 60	        }
 61	    }
 62	
 63	    pub(crate) fn to_json(&self) -> serde_json::Value {
 64	        match self {
 65	            Self::Bool(b) => (*b).into(),
 66	            Self::Int(i) => (*i).into(),
 67	            Self::Float(f) => (*f).into(),
 68	            Self::Str(s) => s.clone().into(),
 69	        }
 70	    }
 71	
 72	    /// Does the pair from `defaults read-type` ("boolean", "integer", ...)
 73	    /// and `defaults read` (raw value; booleans print as 1/0) match this
 74	    /// value? Types are compared strictly: an integer 1 does not satisfy a
 75	    /// configured `true` — `mise bootstrap macos defaults apply` converges it to the typed
 76	    /// value.
 77	    fn matches(&self, read_type: &str, raw: &str) -> bool {
 78	        match self {
 79	            Self::Bool(b) => read_type == "boolean" && raw == if *b { "1" } else { "0" },
 80	            Self::Int(i) => read_type == "integer" && raw.parse::<i64>() == Ok(*i),
 81	            Self::Float(f) => {
 82	                read_type == "float" && raw.parse::<f64>().is_ok_and(|v| (v - f).abs() < 1e-9)
 83	            }
 84	            Self::Str(s) => read_type == "string" && raw == s,
 85	        }
 86	    }
 87	}
 88	
 89	impl std::fmt::Display for DefaultsValue {
 90	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
 91	        match self {
 92	            Self::Bool(b) => write!(f, "{b}"),
 93	            Self::Int(i) => write!(f, "{i}"),
 94	            Self::Float(v) => write!(f, "{v}"),
 95	            Self::Str(s) => write!(f, "{s}"),
 96	        }
 97	    }
 98	}
 99	
100	#[derive(Debug, Clone, PartialEq)]
101	pub(crate) enum DefaultsState {
102	    /// current value matches the config
103	    Set,
104	    /// a value exists but differs from the config (in value or type)
105	    Differs { current: String },
120	pub(crate) fn unavailable_reason() -> String {
121	    if cfg!(target_os = "macos") {
122	        "`defaults` not found".to_string()
123	    } else {
124	        "only available on macos".to_string()
125	    }
126	}
127	
128	/// Query the current state of each entry. Side-effect free.
